/**
 * Researched attributes per sub-category, as form fields.
 *
 * Data: src/api/data/attributeSets.json, generated by catalog/attributes/build.js from the
 * catalogue's attribute research (never edit it by hand). For each sub-category it lists
 * the full attribute set, the ordered variant axes and the basic form (the least a shop
 * fills). The catalogue holds the same data in catalog.attribute_sets.
 *
 *   basicFormFields(sub, legacyFields)  the sub-category's default listing form
 *   enableableFields(subKey, baseKeys)  attributes a store can switch on (shop_form_overrides
 *                                       enabled_attributes), excluding the form and the axes
 *   variantAxes(subKey)                 ordered variant axis keys
 *   fieldFor(subKey, key)               one attribute as a form field
 */
const fs = require('fs');
const path = require('path');
const { FIELD_SOURCE_DEFAULTS, FILTERABLE_TYPES } = require('./formSchema');

const DATA_FILE = path.join(__dirname, '..', 'data', 'attributeSets.json');
const MAX_OPTIONS = 50;

const load = () => {
  try {
    const data = JSON.parse(fs.readFileSync(DATA_FILE, 'utf8'));
    return { definitions: data.definitions || {}, subCategories: data.sub_categories || {} };
  } catch (err) {
    if (err.code !== 'ENOENT') console.warn(`[attributeSets] ${DATA_FILE} unreadable: ${err.message}`);
    return { definitions: {}, subCategories: {} };
  }
};
const DATA = load();

const hasSet = (subKey) => Boolean(subKey && DATA.subCategories[subKey]);
const setFor = (subKey) => DATA.subCategories[subKey] || { variant_axes: [], basic_form: [], attributes: [] };
const variantAxes = (subKey) => [...(setFor(subKey).variant_axes || [])];

const UNIT_LABEL = { g: 'g', kg: 'kg', ml: 'ml', l: 'L', cm: 'cm', mm: 'mm', m: 'm', inch: 'in', w: 'W', kw: 'kW', gb: 'GB', tb: 'TB', mah: 'mAh', min: 'min', h: 'hours', day: 'days', month: 'months', sqft: 'sq ft' };

/** A dictionary definition + set row → a form field (services/formSchema field shape). */
const toField = (key, def, row) => {
  const values = (def.values || []).slice(0, MAX_OPTIONS);
  const label = String(def.label || key).slice(0, 60);
  let field;
  switch (def.type) {
    case 'enum':
      field =
        values.length && !def.open_values
          ? { type: 'select', options: values }
          : { type: 'text', placeholder: values.length ? `e.g. ${values.slice(0, 3).join(', ')}` : undefined };
      break;
    case 'multi_enum':
      // The form builder has no multi-select yet: comma-separated text, examples as a hint
      field = { type: 'text', placeholder: values.length ? `e.g. ${values.slice(0, 3).join(', ')}` : 'Comma separated' };
      break;
    case 'measure': {
      const unit = def.default_unit ? UNIT_LABEL[String(def.default_unit).toLowerCase()] || def.default_unit : '';
      field = { type: 'number', label: unit ? `${label} (${unit})`.slice(0, 60) : label };
      break;
    }
    case 'textarea':
    case 'number':
    case 'boolean':
    case 'date':
    case 'text':
      field = { type: def.type };
      break;
    default:
      field = { type: 'text' };
  }
  const out = { key, label, ...field };
  if (out.placeholder === undefined) delete out.placeholder;
  if (row.level === 'statutory' || row.level === 'required') out.required = true;
  if (row.level === 'statutory') out.statutory = true;
  if (row.filterable && FILTERABLE_TYPES.includes(out.type)) out.filterable = true;
  if (row.owner === 'catalog') {
    const known = FIELD_SOURCE_DEFAULTS[key];
    out.source = 'catalog';
    out.catalog_path = known ? known.catalog_path : `attributes.${key}`;
  } else {
    out.source = 'store';
  }
  return out;
};

/** One attribute of a sub-category as a form field, or null. */
const fieldFor = (subKey, key) => {
  const row = (setFor(subKey).attributes || []).find((a) => a.key === key);
  const def = DATA.definitions[key];
  return row && def ? toField(key, def, row) : null;
};

/**
 * The basic listing form of a sub-category (variant axes excluded: they live on variants).
 * A key the old template already had keeps that field's wording, options and default, with
 * the researched level and ownership applied. Returns null when no research covers it.
 */
const basicFormFields = (sub, legacyFields = []) => {
  if (!hasSet(sub.key)) return null;
  const set = setFor(sub.key);
  const axes = new Set(set.variant_axes || []);
  const legacy = new Map((legacyFields || []).map((f) => [f.key, f]));
  return (set.basic_form || [])
    .filter((key) => !axes.has(key))
    .map((key) => {
      const researched = fieldFor(sub.key, key);
      if (!researched) return null;
      const old = legacy.get(key);
      if (!old) return researched;
      const merged = { ...old, required: researched.required || undefined, statutory: researched.statutory || undefined };
      if (researched.source === 'catalog') {
        merged.source = 'catalog';
        merged.catalog_path = old.catalog_path || researched.catalog_path;
      }
      Object.keys(merged).forEach((k) => merged[k] === undefined && delete merged[k]);
      return merged;
    })
    .filter(Boolean);
};

/** Attributes a store may switch on for this sub-category, in research order. */
const enableableFields = (subKey, baseKeys = []) => {
  if (!hasSet(subKey)) return [];
  const set = setFor(subKey);
  const skip = new Set([...(set.variant_axes || []), ...baseKeys]);
  return (set.attributes || [])
    .filter((a) => !skip.has(a.key))
    .map((a) => {
      const field = fieldFor(subKey, a.key);
      // An enabled extra is never forced on the store: required only applies to the basic form
      if (field && a.level !== 'statutory') delete field.required;
      return field ? { ...field, level: a.level } : null;
    })
    .filter(Boolean);
};

module.exports = { hasSet, variantAxes, fieldFor, basicFormFields, enableableFields };
